            let state = self.lock();
            (state.cursor_col, state.cursor_row)
        }

        /// Whether the cursor is hidden (tracks `?25l` / `?25h`).
        fn cursor_hidden(&self) -> bool {
            self.lock().cursor_hidden
        }

