                    rows,
                    lines: vec![vec![None; columns]; rows],
                    cursor_row: 0,
                    cursor_col: 0,
                    italic: false,
                    cursor_hidden: false,
                    writes: Vec::new(),
                    input_handler: None,
                    resize_handler: None,
